// This control sequence is generated by Kani, never inferred from the user's keywords.
// Only one handoff is allowed: specialist output is text, not another tool call.
export const CIDE_CALL = 'CIDE';
export const maybeCide = text => CIDE_CALL.startsWith(text) || /^CIDE\s*$/.test(text);

export function codingContext(model, messages, maxTokens) {
  const reserve = Math.min(maxTokens, Math.max(16, Math.floor(model.config.context / 3)));
  const latest = messages.at(-1);
  if (!latest || latest.role !== 'user') throw new Error('Cide needs a user request.');
  if (model.tokenizer.encode(latest.content).length + 3 > model.config.context - reserve)
    throw new Error('This request is too long for Cide. Send a smaller function or source excerpt.');
  // Keep whole recent exchanges; never silently cut source code in the latest request.
  let retained = messages.slice(-15);
  const size = () => retained.reduce((n, m) => n + model.tokenizer.encode(m.content).length + 2, 1);
  while (retained.length > 1 && size() > model.config.context - reserve) retained = retained.slice(2);
  return retained;
}

// `sampling` holds further Model.generate settings (topP, seed's random, penalties) for the API.
export async function* cideAnswer(messages, { load, maxTokens = 4096, temperature = 0, sampling = {}, cancelled = () => false, pause = () => Promise.resolve() }) {
  if (cancelled()) return;
  const model = await load();
  if (cancelled()) return;
  const retained = codingContext(model, messages, maxTokens);
  for (const text of model.generate(retained, { temperature, ...sampling, maxTokens, repeats: false })) {
    if (cancelled()) return;
    yield text;
    await pause();
  }
}
